def enrollment(G):
    W = G.W
    for g in GROUPS:
        name, table = ENROL_FILES[g]
        f = G.lf(name, "SLA enrollment register - %s" % g.title())
        t = G.tab(f, table)
        last = {}
        for e in W.enroll[g]:
            cls = e["cls"] or last.get(e["sub"]) or "STD"
            last[e["sub"]] = cls
            eff = e["eff"]
            if g == "east":
                eff = "%s.%s.%s" % (eff[8:10], eff[5:7], eff[:4])
            elif g == "west":
                eff = eff.replace("-", "")
            G.put(t, {"enrollment_id": e["id"], "subscription_id": e["sub"],
                      "effective": eff, "action": e["action"], "sla_class": cls},
                  G.k_sub(e["sub"]))


def contracts(G):
    W = G.W
