''',
    'g_tel.py': r'''"""Collector infrastructure: hosts, lanes, sampling, deploy/schema state, quarantine,
edge clocks and SDK builds.  Telemetry rows are produced by g_tel2."""
import bisect

from world import REGION, RCODES, PRODUCTS, CDN_PRODUCTS, EDGE_PRODUCTS, SVC_PRODUCTS

COLLECTORS = [("LB", 1, "LB"), ("SVC", 2, "SVC"), ("EDGE", 3, "EDGE"),
              ("CDN-ATT", 4, "CDN"), ("CDN-XML", 5, "CDN"), ("SDK", 6, "NONE")]
PREC = {c: p for c, p, _ in COLLECTORS}
LANE = {c: l for c, _, l in COLLECTORS}
V6 = [("record_id", 12, "l"), ("host", 16, "l"), ("subscription", 10, "l"),
      ("reading", 14, "l"), ("requests", 7, "r"), ("err_5xx", 6, "r"),
      ("err_429", 6, "r"), ("err_4xx", 6, "r"), ("seq", 4, "r"), ("batch_id", 14, "l")]
V7 = [("record_id", 12, "l"), ("subscription", 10, "l"), ("host", 16, "l"),
      ("reading", 14, "l"), ("requests", 8, "r"), ("err_5xx", 7, "r"),
      ("err_429", 7, "r"), ("err_4xx", 7, "r"), ("seq", 4, "r"), ("batch_id", 14, "l")]
EDGE_GROUPS = {"a": ("central", "east"), "b": ("north", "south"), "c": ("west",)}
GAPS = {"P1": ("2026-08-20", "2026-08-23"), "P2": ("2026-09-10", "2026-09-13")}


def coverage(product):
    out = ["LB"]
    if product in SVC_PRODUCTS:
        out.append("SVC")
    if product in EDGE_PRODUCTS:
        out.append("EDGE")
    if product in CDN_PRODUCTS:
        out += ["CDN-ATT", "CDN-XML"]
    out.append("SDK")
    return out


def hosts(G):
    W, r = G.W, G.R("hosts")
    G.HOSTS_BY = {}
    G.MISROUTE = {}
    for hid, h in sorted(W.hosts.items()):
        G.HOSTS_BY.setdefault((h["product"], h["region"], h["lane"]), []).append(hid)
        if h["reported"] != h["lane"]:
            G.MISROUTE.setdefault((h["product"], h["region"], h["reported"]), []).append(hid)
    G.SVC_ALIAS = dict(W.svc_alias)
    k = len(G.SVC_ALIAS)
    for h in sorted(W.hosts):  # misrouted hosts reporting the SVC lane also carry a node alias
        hh = W.hosts[h]
        if hh["reported"] == "SVC" and hh["lane"] != "SVC":
            k += 1
            G.SVC_ALIAS["svc-node-%04d" % k] = h
    G.NODE_OF = {h: n for n, h in G.SVC_ALIAS.items()}
    f = G.lf("host_inventory.csv")
    f.meta["comments"] = ["Corvid fleet inventory export (lane column is the self-reported collector lane)"]
    t = G.tab(f, "records")
    for hid, h in sorted(W.hosts.items()):
        G.put(t, {"host": hid, "region": h["region"], "product": h["product"],
                  "lane": h["reported"], "rack": h["rack"],
                  "commissioned": h["commissioned"]}, G.k_pr(h["product"], h["region"]))
    f = G.lf("telemetry_collection_standard.docx",
             "Telemetry Collection Standard TCS-7 (SLA evidence)")
    t = G.tab(f, "Collector precedence", grow=False)
    for c, p, l in COLLECTORS:
        G.put(t, {"collector": c, "precedence": p, "lane": l})
    t = G.tab(f, "Edge record layout V6", grow=False)
    for c, w, _ in V6:
        G.put(t, {"field": c, "width": w})
    t = G.tab(f, "Collector gap windows", grow=False)
    gaps = [("GAP-0001", "ist1", "LB", "2026-08-20", "2026-08-23"),
            ("GAP-0002", "ist1", "LB", "2026-09-10", "2026-09-13"),
            ("GAP-0003", "hel1", "CDN-XML", "2026-07-07", "2026-07-08"),
            ("GAP-0004", "mad1", "SVC", "2026-06-02", "2026-06-03")]
    for gid, reg, col, a, b in gaps:
        G.put(t, {"gap_id": gid, "region": reg, "collector": col,
                  "from": a + "T00:00:00Z", "to": b + "T00:00:00Z"})
    g0, g1 = GAPS[G.pid]
    G.GAP = (G.dts(g0), G.dts(g1))
    t = G.tab(f, "Host lane assignments")
    for hid, h in sorted(W.hosts.items()):
        G.put(t, {"host": hid, "lane": h["lane"],
                  "assigned_on": h["commissioned"]}, G.k_pr(h["product"], h["region"]))


def sampling(G):
    r = G.R("sampling")
    f = G.lf("lb_sampling.parquet")
    t = G.tab(f, "records")
    G.SAMP = {}
    lb = sorted(h for h, x in G.W.hosts.items() if x["lane"] == "LB")
    n = 0
    rows = []
    for h in lb:
        one = r.weighted([1, 2, 5, 10], [70, 12, 10, 8])
        rows.append((G.dts("2026-01-01") + r.below(86400 * 30), h, one))
    for _ in range(5300 - len(lb)):
        h = lb[r.below(len(lb))]
        rows.append((G.Q + r.below(G.E - G.Q + 86400 * 20), h,
                     r.weighted([1, 2, 5, 10], [55, 20, 15, 10])))
    rows.sort()
    for eff, h, one in rows:
        n += 1
        sid = "SMP-%06d" % n
        G.SAMP.setdefault(h, []).append((eff, sid, one))
        G.put(t, {"sampling_id": sid, "host": h, "effective_from": eff, "one_in": one},
              G.k_pr(G.W.hosts[h]["product"], G.W.hosts[h]["region"]))
    for h in G.SAMP:
        G.SAMP[h].sort()


def one_in(G, host, t):
    xs = G.SAMP.get(host, [])
    best = 1
    for eff, _, one in xs:
        if eff <= t:
            best = one
    return best


def deploy(G):
    W, r = G.W, G.R("deploy")
    lb = sorted(h for h, x in W.hosts.items() if x["lane"] == "LB")
    G.BASE = {}
    f = G.lf("schema_registry.yaml")
    f.meta["comments"] = ["LB access-log schema registry"]
    t = G.tab(f, "versions", grow=False)
    G.put(t, {"version": "v1", "err_5xx_includes_429": True,
              "notes": "err_5xx counts every 5xx-class and throttled (429) response"})
    G.put(t, {"version": "v2", "err_5xx_includes_429": False,
              "notes": "err_5xx excludes throttled responses; err_429 reported separately"})
    t = G.tab(f, "baseline")
    for h in sorted(W.hosts):
        v = "v1" if r.chance(0.55) else "v2"
        G.BASE[h] = v
        G.put(t, {"host": h, "schema": v, "as_of": G.FIRST},
              G.k_pr(W.hosts[h]["product"], W.hosts[h]["region"]))
    # waves and manifests
    f = G.lf("deploy_manifests.xml")
    f.meta["root"] = "DeployManifests"
    t = G.tab(f, "Member")
    members = {}
    mid = 0
    for w in range(1, 211):
        wid = "WV-%04d" % w
        revs = 2 if r.chance(0.15) else 1
        for rev in range(1, revs + 1):
            hs = r.sample(lb, 22 + r.below(6))
            members[wid] = (rev, hs)
            for h in hs:
                mid += 1
                G.put(t, {"member_id": "MB-%06d" % mid, "wave": wid, "revision": rev,
                          "host": h}, G.k_pr(W.hosts[h]["product"], W.hosts[h]["region"]))
    G.WAVE = {w: set(hs) for w, (rev, hs) in members.items()}
    # events
    f = G.lf("deploy_events.log")
    f.meta["comments"] = ["deployer audit stream; seq is the deployer commit sequence"]
    t = G.tab(f, "records")
    evs = []
    waves = sorted(G.WAVE)
    for i in range(150):
        ts = G.S + r.below(G.E - G.S)
        wid = waves[r.below(len(waves))]
        kind = "ROLLOUT" if r.chance(0.65) else "ROLLBACK"
        evs.append([ts, kind, "v2" if kind == "ROLLOUT" else "v1", wid])
    evs.sort()
    seqs = list(range(1001, 1001 + len(evs)))
    for i in range(0, len(seqs) - 1, 9):     # late-committed events: seq order != ts order
        seqs[i], seqs[i + 1] = seqs[i + 1], seqs[i]
    G.SCH_EV = {}
    aborted = []
    lines = []
    for (ts, kind, sch, wid), seq in zip(evs, seqs):
        eid = "DE-%06d" % seq
        ab = kind == "ROLLOUT" and r.chance(0.12)
        if ab:
            aborted.append(eid)
        else:
            for h in G.WAVE[wid]:
                G.SCH_EV.setdefault(h, []).append((seq, ts, sch))
        lines.append((ts, eid, kind, sch, wid, seq))
    G.ABORTED = aborted
    n = 5000
    noise = 0
    while len(lines) < 5600:
        noise += 1
        ts = G.S - 86400 * 3 + r.below(G.E - G.S + 86400 * 3)
        kind = r.weighted(["HEARTBEAT", "CANARY"], [80, 20])
        wid = waves[r.below(len(waves))] if kind == "CANARY" else None
        lines.append((ts, "DE-%06d" % (n + noise * 3), kind, None, wid, None))
    lines.sort()
    for ts, eid, kind, sch, wid, seq in lines:
        keys = []
        if wid and kind in ("ROLLOUT", "ROLLBACK"):
            h = sorted(G.WAVE[wid])[0]
            keys = G.k_pr(W.hosts[h]["product"], W.hosts[h]["region"])
        G.put(t, {"event_id": eid, "ts": G.iso_off(ts), "level": "INFO",
                  "component": "deployer", "event": kind, "schema": sch, "wave": wid,
                  "seq": seq}, keys)


def schema_at(G, host, t):
    best = None
    for seq, ts, sch in G.SCH_EV.get(host, ()):
        if ts <= t and (best is None or seq > best[0]):
            best = (seq, sch)
    return best[1] if best else G.BASE[host]


def quarantine(G):
    W, r = G.W, G.R("quarantine")
    hs = sorted(W.hosts)
    f = G.lf("telemetry_quarantine.json")
    f.meta["head"] = {"source": "fleet-health", "generated": G.iso_off(G.E + 86400 * 2)}
    t = G.tab(f, "quarantine")
    G.QUAR = {}
    lo = G.dts("2026-01-01")
    span = G.E + 86400 * 10 - lo
    for i in range(5200):
        h = hs[r.below(len(hs))]
        a = lo + r.below(span)
        if i % 3 == 0:
            a = G.S + r.below(G.E - G.S)
        b = a + 3600 * (1 + r.below(48))
        st = "ACTIVE" if r.chance(0.8) else "LIFTED"
        if st == "ACTIVE":
            G.QUAR.setdefault(h, []).append((a, b))
        G.put(t, {"quarantine_id": "QR-%05d" % (i + 1), "host": h, "from": G.iso_off(a),
                  "to": G.iso_off(b), "status": st},
              G.k_pr(W.hosts[h]["product"], W.hosts[h]["region"]))


def quarantined(G, host, t):
    return any(a <= t < b for a, b in G.QUAR.get(host, ()))


def clocks(G):
    W, r = G.W, G.R("clocks")
    G.SKEW = {}
    lo = G.dts("2026-01-01")
    hi = G.E + 86400 * 5
    n = 0
    for k, groups in EDGE_GROUPS.items():
        f = G.lf("host_clock_edge_%s.ini" % k)
        f.meta["comments"] = ["edge host clock-offset measurements (skew_s = host clock minus true UTC, seconds)"]
        t = G.tab(f, "measure")
        hosts_k = [h for h in W.edge_hosts if REGION[W.hosts[h]["region"]]["group"] in groups]
        per = {"a": 31, "b": 27, "c": 62}[k]
        rows = []
        for h in hosts_k:
            step = (hi - lo) // per
            for j in range(per):
                at = lo + j * step + r.below(step - 3600)
                sk = r.randint(-400, 400)
                if sk == -1:
                    sk = 1
                rows.append((at, h, sk))
        rows.sort()
        for at, h, sk in rows:
            n += 1
            mid = "MS-%06d" % n
            G.SKEW.setdefault(h, []).append((at, sk))
            G.put(t, {"measurement_id": mid, "host": h, "measured_at": G.iso_off(at),
                      "skew_s": sk}, G.k_pr(W.hosts[h]["product"], W.hosts[h]["region"]))
    for h in G.SKEW:
        G.SKEW[h].sort()
        G.SKEW_T = None


def skew_at(G, host, u):
    xs = G.SKEW.get(host, [])
    i = bisect.bisect_right(xs, (u, 10 ** 9)) - 1
    return xs[i][1] if i >= 0 else 0


def builds(G):
    r = G.R("builds")
    f = G.lf("sdk_builds.json")
    f.meta["head"] = {"source": "sdk-release-registry"}
    t = G.tab(f, "builds")
    G.BUILDS = []
    plats = ["android", "ios", "web", "python", "go", "java", "dotnet", "rust"]
    seen = set()
    while len(G.BUILDS) < 5200:
        p = r.choice(plats)
        b = "sdk-%s-%d.%d.%d" % (p, r.randint(3, 6), r.below(30), r.below(40))
        if b in seen:
            continue
        seen.add(b)
        clock = "DEVICE" if r.chance(0.4) else "SERVER"
        st = "RECALLED" if r.chance(0.05) else "GA"
        G.BUILDS.append((b, p, clock, st))
        G.put(t, {"build": b, "platform": p, "clock": clock, "status": st,
                  "released": G.day(G.dts("2024-01-01") + r.below(86400 * 960))})
    G.GA_SERVER = [b for b, p, c, s in G.BUILDS if s == "GA" and c == "SERVER"]
    G.GA_DEVICE = [b for b, p, c, s in G.BUILDS if s == "GA" and c == "DEVICE"]
    G.RECALLED = [b for b, p, c, s in G.BUILDS if s == "RECALLED"]
    ga = G.GA_SERVER + G.GA_DEVICE
    G.WITHDRAWN = sorted(r.sample(ga, 45))
    wd = set(G.WITHDRAWN)
    G.GA_SERVER = [b for b in G.GA_SERVER if b not in wd]
    G.GA_DEVICE = [b for b in G.GA_DEVICE if b not in wd]
    G.CLOCK = {b: c for b, p, c, s in G.BUILDS}


def build(G):
    hosts(G)
    sampling(G)
    deploy(G)
    quarantine(G)
    clocks(G)
    builds(G)
