FILES = sorted(SCHEMA)
REGISTER = "audit_control_register.pdf"

_UTC = _dt.timezone.utc
_UNIX = _dt.datetime(1970, 1, 1, tzinfo=_UTC)
_INVISIBLE = "\u200b\ufeff\u00a0\u202f\u2060"
_WIDTH = {"SUB": 6, "ACC": 5, "INS": 7}


def half_even(x):
    """Round a rational to the nearest integer, ties to even (Fraction.__round__ semantics)."""
    return int(round(_F(x)))


def add_days(iso_day, n):
    y, m, d = (int(p) for p in iso_day.split("-"))
    return (_dt.date(y, m, d) + _dt.timedelta(days=n)).isoformat()


def snake(key):
    out = []
    for i, ch in enumerate(str(key)):
        if ch.isupper() and i and (key[i - 1].islower() or key[i - 1].isdigit()):
            out.append("_" + ch.lower())
        else:
            out.append(ch)
    return "".join(out)


def n_id(value):
    """Canonical PREFIX-digits identifier, or None for a malformed one."""
    if value is None:
        return None
    text = "".join(ch for ch in str(value) if ch not in _INVISIBLE and not ch.isspace())
    if not text or any(ord(ch) > 127 for ch in text):
        return None
    text = text.upper().replace("_", "-")
    prefix = text.rstrip("0123456789")
    digits = text[len(prefix):]
    prefix = prefix[:-1] if prefix.endswith("-") else prefix
    if not digits or not prefix.isalpha():
        return None
    if prefix in _WIDTH and len(digits) != _WIDTH[prefix]:
        return None
    return prefix + "-" + digits


def _midnight(iso_day):
    y, m, d = (int(p) for p in iso_day.split("-"))
    return int((_dt.datetime(y, m, d, tzinfo=_UTC) - _UNIX).total_seconds())


def _serial_seconds(serial, epoch1904):
    origin = _dt.datetime(1904, 1, 1, tzinfo=_UTC) if epoch1904 else _dt.datetime(1899, 12, 30, tzinfo=_UTC)
    return int((origin - _UNIX).total_seconds()) + half_even(_F(str(serial)) * 86400)


def n_ts(value, epoch1904=False):
    """Instant in epoch seconds from ISO text, epoch seconds/milliseconds or a spreadsheet serial."""
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        raise ValueError("boolean is not an instant")
    if isinstance(value, _dt.datetime):
        v = value if value.tzinfo else value.replace(tzinfo=_UTC)
        return int((v - _UNIX).total_seconds())
    if isinstance(value, _dt.date):
        return _midnight(value.isoformat())
    if isinstance(value, int):
        return value // 1000 if value >= 10 ** 11 else value
    if isinstance(value, float):
        return _serial_seconds(value, epoch1904)
    text = str(value).strip()
    if text.isdigit():
        if len(text) == 8:
            return _midnight(text[:4] + "-" + text[4:6] + "-" + text[6:])
        return int(text) // 1000 if len(text) >= 12 else int(text)
    dotted = _re.fullmatch(r"(\d\d)\.(\d\d)\.(\d{4})", text)
    if dotted:
        return _midnight(dotted.group(3) + "-" + dotted.group(2) + "-" + dotted.group(1))
    if len(text) == 10:
        text += "T00:00:00"
    parsed = _dt.datetime.fromisoformat(text.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=_UTC)
    return int((parsed - _UNIX).total_seconds())


def n_date(value, epoch1904=False):
    """Calendar day as YYYY-MM-DD; None when empty or open-ended (9999-12-31)."""
    if value is None:
        return None
    if isinstance(value, _dt.datetime):
        value = value.date()
    if isinstance(value, _dt.date):
        day = value.isoformat()
    elif isinstance(value, float):
        day = (_UNIX + _dt.timedelta(seconds=_serial_seconds(value, epoch1904))).strftime("%Y-%m-%d")
    else:
        text = str(value).strip()
        if not text:
            return None
        dotted = _re.fullmatch(r"(\d\d)\.(\d\d)\.(\d{4})", text)
        if dotted:
            text = dotted.group(3) + "-" + dotted.group(2) + "-" + dotted.group(1)
        elif len(text) == 8 and text.isdigit():
            text = text[:4] + "-" + text[4:6] + "-" + text[6:]
        day = text[:10]
        _dt.date.fromisoformat(day)
    return None if day == "9999-12-31" else day
