def sla_version_for(sign_date: str) -> str:
    if sign_date < "2024-01-01":
        return "v2"
    if sign_date < "2025-03-01":
        return "v3"
    if sign_date < "2026-02-01":
        return "v4"
    return "v5"


# error-rate threshold (per mille) per version; targets for v2..v4 per class; tiers (below, pct)
THRESHOLD = {"v2": 100, "v3": 50, "v4": 50, "v5": 20}
TARGETS = {"v2": {"STD": "99.0", "PRM": "99.5", "CRT": "99.9"},
           "v3": {"STD": "99.5", "PRM": "99.9", "CRT": "99.95"},
           "v4": {"STD": "99.5", "PRM": "99.9", "CRT": "99.95"}}
# tier rows: (kind, value, pct) kind 'rel' = target minus value, 'abs' = absolute uptime; first match from the
# bottom (most severe) wins.
TIERS = {"v2": [("rel", "0", 10), ("rel", "1.0", 25), ("abs", "95.0", 50)],
         "v3": [("rel", "0", 10), ("abs", "99.0", 25), ("abs", "95.0", 100)],
         "v4": [("rel", "0", 10), ("abs", "99.0", 30), ("abs", "95.0", 100)],
         "v5": [("rel", "0", 10), ("rel", "0.5", 25), ("abs", "99.0", 50), ("abs", "95.0", 100)]}

