@criterion(description="Every deliverable exists, parses, and normalized records carry exactly the documented fields")
def outputs_have_documented_shape(workspace: Path) -> bool:
    try:
        vis = _visible()
        if vis is None:
            return False
        if not all(isinstance(vis[n], dict) for n in JSON_FILES):
            return False
        if vis["summary.json"].get("status") not in ("PUBLISHED", "HELD"):
            return False
        if not isinstance(vis["data_quality.json"].get("sources"), list):
            return False
        return bool(vis["normalized.jsonl"]) and all(sorted(r) == RECORD_KEYS for r in vis["normalized.jsonl"])
    except Exception:
        return False


@criterion(description="Outputs are UTF-8, JSON documents use sorted keys and 2-space indent, and JSON Lines are compact")
def outputs_use_documented_encoding(workspace: Path) -> bool:
    try:
        if not _jsonl_ok((OUT / "normalized.jsonl").read_bytes()):
            return False
        return all(_json_doc_ok((OUT / n).read_bytes()) for n in JSON_FILES)
    except Exception:
        return False


